// Export the product's factory sounds through the same serializer as SAVE AS.
// The distributable is generated by the ordinary, exact-source Product build.
#include "PluginProcessor.h"
#include "PresetOrder.h"
#include "ReleaseInfo.h"
#include <juce_cryptography/juce_cryptography.h>
#include <cmath>
#include <iostream>
#include <map>
#include <memory>
#include <stdexcept>

namespace {
void require(bool condition,const char* message) {
    if(!condition)throw std::runtime_error(message);
}
void requirePublicState(const juce::ValueTree& state) {
    if(state.hasType("USER_IRS") || state.hasType("IR_ASSETS") || state.hasType("MIDI_MAP"))
        require(state.getNumChildren()==0 && state.getNumProperties()==0,
                "Factory pack contains imported IR data, references or personal MIDI mappings");
    for(int i=0;i<state.getNumProperties();++i) {
        const auto key=state.getPropertyName(i).toString().toLowerCase();
        require(key!="path" && key!="filename" && key!="filepath" && key!="token"
                && key!="authorization", "Factory pack contains a local path or credential field");
    }
    for(auto child:state)requirePublicState(child);
}
juce::String fileName(int index,const juce::String& name) {
    juce::String slug;
    for(auto character:name) {
        if((character>='a' && character<='z') || (character>='A' && character<='Z')
            || (character>='0' && character<='9'))slug+=juce::String::charToString(character);
        else if(!slug.endsWithChar('-'))slug+='-';
    }
    return juce::String(index+1).paddedLeft('0',2)+"-"+slug.trimCharactersAtEnd("-")+".chimera";
}
std::map<juce::String,float> parameters(ChimeraProcessor& processor) {
    std::map<juce::String,float> result;
    for(auto* raw:processor.getParameters()) {
        auto* parameter=dynamic_cast<juce::RangedAudioParameter*>(raw);
        require(parameter!=nullptr,"Factory parameter has no stable ID");
        require(std::isfinite(parameter->getValue()),"Factory parameter is not finite");
        require(result.emplace(parameter->paramID,parameter->getValue()).second,
                "Factory parameter IDs are duplicated");
    }
    return result;
}
juce::String parameterDigest(const std::map<juce::String,float>& values) {
    juce::String serialized;
    for(const auto& [id,value]:values)serialized+=id+"="+juce::String(double(value),9)+"\n";
    return juce::SHA256(serialized.toRawUTF8(),serialized.getNumBytesAsUTF8()).toHexString();
}
const char* platform() {
#if JUCE_WINDOWS
    return "windows";
#elif JUCE_MAC
    return "macos";
#elif JUCE_LINUX
    return "linux";
#else
    return "unsupported";
#endif
}
}

int main(int argc,char** argv) {
    try {
        require(argc==2,"Usage: ChimeraFactoryPresetExport OUTPUT_DIRECTORY");
        juce::ScopedJuceInitialiser_GUI initialise;
        std::cout<<std::unitbuf;
        const juce::File directory(juce::String::fromUTF8(argv[1]));
        require(directory.createDirectory().wasOk(),"Cannot create factory pack directory");
        require(spectralforge::selectablePresetCount==48,"Factory pack ordinal inventory changed");
        require(juce::String(CHIMERA_SOURCE_SHA).length()==40,"Export has no full compiled source SHA");
        juce::Array<juce::var> rows;
        juce::Array<juce::var> parameterIDs;
        juce::StringArray expectedFiles;
        for(int index=0;index<spectralforge::selectablePresetCount;++index) {
            // Fresh instances cannot capture a user's imported IRs or MIDI map.
            auto authored=std::make_unique<ChimeraProcessor>();
            authored->loadFactoryPreset(index);
            const auto values=parameters(*authored);
            juce::Array<juce::var> normalized;
            int parameterIndex=0;
            for(const auto& [id,value]:values) {
                if(index==0)parameterIDs.add(id);
                else require(parameterIDs[parameterIndex].toString()==id,
                             "Factory presets do not share a stable parameter inventory");
                normalized.add(double(value));++parameterIndex;
            }
            require(parameterIDs.size()==parameterIndex,"Factory parameter inventory size differs");
            require(std::abs(authored->parameters().getRawParameterValue("output")->load())<1.e-6f,
                    "Factory output is not the authored unity reference");
            juce::MemoryBlock bytes;
            require(authored->tryGetStateInformation(bytes) && bytes.getSize()>8,
                    "Product serializer refused a factory preset");
            const auto xml=juce::AudioProcessor::getXmlFromBinary(bytes.getData(),int(bytes.getSize()));
            require(xml!=nullptr && xml->hasTagName("PARAMS"),"Factory binary state is invalid");
            const auto tree=juce::ValueTree::fromXml(*xml);
            require(int(tree.getProperty("schemaVersion"))==11,"Factory state schema changed");
            requirePublicState(tree);
            const auto name=juce::String::fromUTF8(spectralforge::selectablePresetName(index));
            const auto filename=fileName(index,name);
            require(!expectedFiles.contains(filename),"Factory file names are duplicated");
            expectedFiles.add(filename);
            const auto path=directory.getChildFile(filename);
            require(!path.isSymbolicLink() && path.replaceWithData(bytes.getData(),bytes.getSize()),
                    "Cannot write factory preset");
            juce::MemoryBlock disk;
            require(path.loadFileAsData(disk) && disk==bytes,"Factory file changed while writing");
            auto restored=std::make_unique<ChimeraProcessor>();
            // Make a failed/no-op restore observable even for the first preset.
            auto* output=restored->parameters().getParameter("output");
            output->setValueNotifyingHost(output->convertTo0to1(-17.f));
            restored->setStateInformation(disk.getData(),int(disk.getSize()));
            const auto recalled=parameters(*restored);
            require(values.size()==recalled.size(),"Factory restore changed parameter inventory");
            double maximumError=0;
            for(const auto& [id,value]:values) {
                require(recalled.contains(id),"Factory restore lost a parameter ID");
                maximumError=std::max(maximumError,std::abs(double(value)-recalled.at(id)));
            }
            require(maximumError<1.e-6,"Factory restore changed a stored parameter");
            juce::MemoryBlock savedAgain;
            require(restored->tryGetStateInformation(savedAgain),"Restored preset cannot be saved again");
            const auto restoredXml=juce::AudioProcessor::getXmlFromBinary(savedAgain.getData(),int(savedAgain.getSize()));
            require(restoredXml!=nullptr,"Restored preset serializer returned invalid state");
            const auto restoredTree=juce::ValueTree::fromXml(*restoredXml);
            requirePublicState(restoredTree);
            for(const char* tag:{"EQ_EDIT_STATE","ORIGINAL_PRESET","GUITAR_SIGNATURE"}) {
                const auto before=tree.getChildWithName(tag),after=restoredTree.getChildWithName(tag);
                require(before.isValid()==after.isValid() && (!before.isValid() || before.isEquivalentTo(after)),
                        "Fresh restore changed graphical EQ occupancy or factory identity metadata");
            }
            const auto eqMetadata=tree.getChildWithName("EQ_EDIT_STATE");
            require(eqMetadata.isValid(),"Factory export omitted graphical EQ occupancy metadata");
            auto* row=new juce::DynamicObject();
            row->setProperty("ordinal",index);row->setProperty("name",name);
            row->setProperty("category",spectralforge::selectablePresetCategory(index));
            row->setProperty("file",filename);row->setProperty("size",juce::int64(bytes.getSize()));
            row->setProperty("sha256",juce::SHA256(bytes).toHexString());
            row->setProperty("parameter_count",int(values.size()));
            row->setProperty("parameter_sha256",parameterDigest(values));
            row->setProperty("normalized_parameters",normalized);
            row->setProperty("restore_max_normalized_error",maximumError);
            row->setProperty("output_db",0);row->setProperty("fresh_restore_passed",true);
            row->setProperty("metadata_restore_passed",true);
            row->setProperty("tone_occupied",int(eqMetadata.getProperty("toneOccupied")));
            row->setProperty("final_occupied",int(eqMetadata.getProperty("finalOccupied")));
            rows.add(juce::var(row));
            std::cout<<"PASS FACTORY_PRESET_EXPORT,"<<index<<','<<filename<<','<<maximumError<<'\n';
        }
        expectedFiles.add("factory-preset-pack.json");
        for(const auto& file:directory.findChildFiles(juce::File::findFilesAndDirectories,false))
            require(!file.isSymbolicLink() && expectedFiles.contains(file.getFileName()),
                    "Factory pack directory contains an unexpected or stale file");
        auto* report=new juce::DynamicObject();
        report->setProperty("schema","spectralforge.chimera.factory-preset-pack.v1");
        report->setProperty("product_version",CHIMERA_PREVIEW_VERSION);
        report->setProperty("source_sha",CHIMERA_SOURCE_SHA);
        report->setProperty("platform",platform());
        report->setProperty("beta_mode",CHIMERA_BETA_MODE);
        report->setProperty("beta_expires_at_utc",CHIMERA_BETA_EXPIRY_UTC);
        report->setProperty("preset_count",rows.size());
        report->setProperty("parameter_ids",parameterIDs);
        report->setProperty("serializer","ChimeraProcessor::tryGetStateInformation / setStateInformation");
        report->setProperty("state_schema_version",11);
        report->setProperty("fresh_processor_restore_passed",true);
        report->setProperty("fresh_gui_metadata_restore_passed",true);
        report->setProperty("personal_ir_included",false);
        report->setProperty("personal_midi_mapping_included",false);
        report->setProperty("actual_daw_acceptance",false);
        report->setProperty("listening_acceptance",false);
        report->setProperty("presets",rows);
        const auto manifest=directory.getChildFile("factory-preset-pack.json");
        require(!manifest.isSymbolicLink() && manifest.replaceWithText(juce::JSON::toString(juce::var(report),true)),
                "Cannot save factory pack manifest");
        std::cout<<"PASS: 48 public .chimera presets exported and restored through the product serializer\n";
        return 0;
    } catch(const std::exception& error) {
        std::cerr<<"Factory preset export stopped: "<<error.what()<<'\n';
        return 1;
    }
}
